function normalizeLanguage(v){return String(v||'').toLowerCase().startsWith('de')?'de':'en'}
function setLanguage(v){
 const l=normalizeLanguage(v);document.body.classList.remove('lang-en','lang-de');document.body.classList.add('lang-'+l);document.documentElement.lang=l;
 document.querySelectorAll('.lang button[data-switch-lang]').forEach(b=>b.classList.toggle('active',b.dataset.switchLang===l));
 document.querySelectorAll('a[data-keep-lang="true"]').forEach(a=>{const base=a.dataset.baseHref||a.getAttribute('href').split('?')[0].split('#')[0];const hash=(a.getAttribute('href').match(/#.*$/)||[''])[0];a.dataset.baseHref=base;a.href=base+'?lang='+l+hash});
 document.querySelectorAll('[data-placeholder-'+l+']').forEach(e=>e.placeholder=e.getAttribute('data-placeholder-'+l));
 document.querySelectorAll('img[data-lang-image="ribbon"]').forEach(img=>{const ext=img.src.toLowerCase().includes('.jpg')?'jpg':'png';img.src='assets/ribbon_'+l+'.'+ext});
 try{localStorage.setItem('anibim-lang',l)}catch(e){}
 document.dispatchEvent(new CustomEvent('anibim-language-changed',{detail:{language:l}}));
}
(function(){const q=new URLSearchParams(location.search);let l=q.get('lang');if(!l){try{l=localStorage.getItem('anibim-lang')}catch(e){}}setLanguage(l||navigator.language||'en')})();


// AniBIM Assistant — 100 bilingual predefined answers with guided follow-up questions.
(function(){
 const FAQS=[{"qEn":"What is AniBIM FT?","aEn":"AniBIM FT is a productivity add-in for Autodesk Revit focused on selection, assemblies, visibility, modelling, reinforcement documentation, quality control and coordination.","qDe":"Was ist AniBIM FT?","aDe":"AniBIM FT ist ein Produktivitäts-Add-in für Autodesk Revit mit Fokus auf Auswahl, Baugruppen, Sichtbarkeit, Modellierung, Bewehrungsdokumentation, Qualitätskontrolle und Koordination."},{"qEn":"Which Revit versions are supported?","aEn":"AniBIM FT supports Autodesk Revit 2024, 2025, 2026 and 2027. The installer lets you select the supported Revit versions installed on your computer.","qDe":"Welche Revit-Versionen werden unterstützt?","aDe":"AniBIM FT unterstützt Autodesk Revit 2024, 2025, 2026 und 2027. Im Installer können Sie die unterstützten, auf Ihrem Computer installierten Revit-Versionen auswählen."},{"qEn":"How do I request a trial?","aEn":"Open the Trial page and request installer access. After installation, AniBIM FT starts the built-in trial automatically when no valid commercial licence is present.","qDe":"Wie fordere ich eine Testversion an?","aDe":"Öffnen Sie die Seite Testversion und fordern Sie Installer-Zugriff an. Nach der Installation startet AniBIM FT die integrierte Testversion automatisch, wenn keine gültige kommerzielle Lizenz vorhanden ist."},{"qEn":"How is the licence activated?","aEn":"Install AniBIM FT and start Revit. For a commercial licence, open Settings → License, copy the Machine ID or use Request License, then install the returned machine-bound licence file.","qDe":"Wie wird die Lizenz aktiviert?","aDe":"Installieren Sie AniBIM FT und starten Sie Revit. Für eine kommerzielle Lizenz öffnen Sie Einstellungen → Lizenz, kopieren die Maschinen-ID oder verwenden Lizenz anfordern und installieren anschließend die erhaltene maschinengebundene Lizenzdatei."},{"qEn":"Is the licence machine-bound?","aEn":"Yes. Trial and standard licences are machine-bound. A hardware or computer change may require a new licence file.","qDe":"Ist die Lizenz an einen Computer gebunden?","aDe":"Ja. Test- und Standardlizenzen sind maschinengebunden. Bei einem Hardware- oder Computerwechsel kann eine neue Lizenzdatei erforderlich sein."},{"qEn":"Where is AniBIM FT in Revit?","aEn":"After installation and successful loading, AniBIM FT appears as its own ribbon tab in Revit.","qDe":"Wo finde ich AniBIM FT in Revit?","aDe":"Nach Installation und erfolgreichem Laden erscheint AniBIM FT als eigene Registerkarte im Revit-Menüband."},{"qEn":"What does Rule Selection do?","aEn":"Rule Selection builds controlled selections using one or more property rules, helping teams select model elements consistently.","qDe":"Was macht die Regelauswahl?","aDe":"Die Regelauswahl erstellt kontrollierte Auswahlen anhand einer oder mehrerer Eigenschaftsregeln und ermöglicht konsistente Modellauswahlen."},{"qEn":"What does Invert do?","aEn":"Invert reverses the active selection so currently unselected eligible elements become selected and selected elements are removed.","qDe":"Was macht Umkehren?","aDe":"Umkehren kehrt die aktive Auswahl um: geeignete nicht ausgewählte Elemente werden ausgewählt und ausgewählte Elemente entfernt."},{"qEn":"What is Assembly Browser?","aEn":"Assembly Browser helps inspect and navigate Revit assemblies and their members from a dedicated interface.","qDe":"Was ist der Assembly Browser?","aDe":"Der Assembly Browser unterstützt das Prüfen und Navigieren von Revit-Baugruppen und deren Mitgliedern in einer eigenen Oberfläche."},{"qEn":"What does Select Similar do?","aEn":"Select Similar provides category-, type- or custom-based matching so related elements can be selected quickly.","qDe":"Was macht Ähnliche auswählen?","aDe":"Ähnliche auswählen bietet Kategorie-, Typ- oder benutzerdefinierte Vergleiche, um zusammengehörige Elemente schnell auszuwählen."},{"qEn":"What does Assembly Creator do?","aEn":"Assembly Creator creates a Revit assembly from selected production elements and guides the main-member and naming workflow.","qDe":"Was macht der Baugruppenersteller?","aDe":"Der Baugruppenersteller erstellt aus ausgewählten Produktionselementen eine Revit-Baugruppe und führt durch Hauptbauteil- und Benennungsworkflow."},{"qEn":"What does Assembly Editor do?","aEn":"Assembly Editor updates the membership of an existing assembly without rebuilding it from scratch.","qDe":"Was macht der Baugruppen-Editor?","aDe":"Der Baugruppen-Editor ändert die Mitglieder einer vorhandenen Baugruppe, ohne sie vollständig neu zu erstellen."},{"qEn":"What is Visibility Browser?","aEn":"Visibility Browser provides a structured way to review and control element visibility in the active view.","qDe":"Was ist der Sichtbarkeits-Browser?","aDe":"Der Sichtbarkeits-Browser bietet eine strukturierte Möglichkeit, die Elementsichtbarkeit in der aktiven Ansicht zu prüfen und zu steuern."},{"qEn":"What does Spotlight do?","aEn":"Spotlight makes surrounding context transparent so the selected elements remain visually prominent.","qDe":"Was macht Hervorheben?","aDe":"Hervorheben stellt den umgebenden Kontext transparent dar, damit ausgewählte Elemente deutlich sichtbar bleiben."},{"qEn":"What does Transparent Selected do?","aEn":"Transparent Selected temporarily displays the selected elements transparently in the active view.","qDe":"Was macht Transparent?","aDe":"Transparent stellt die ausgewählten Elemente vorübergehend transparent in der aktiven Ansicht dar."},{"qEn":"What does Toggle Parts do?","aEn":"Toggle Parts switches the active view between original elements and their Revit Parts representation where applicable.","qDe":"Was macht Teile umschalten?","aDe":"Teile umschalten wechselt die aktive Ansicht zwischen Originalelementen und ihrer Revit-Teiledarstellung, sofern verfügbar."},{"qEn":"What does Beam Length do?","aEn":"Beam Length edits or controls structural framing length through the AniBIM modelling workflow.","qDe":"Was macht Trägerlänge?","aDe":"Trägerlänge bearbeitet oder steuert die Länge von Tragwerkselementen über den AniBIM-Modellierungsworkflow."},{"qEn":"What are Toggle Start Join and Toggle End Join?","aEn":"These commands enable or disable Revit beam joining independently at the start or end of selected framing elements.","qDe":"Was sind Start- und Endverbindung umschalten?","aDe":"Diese Befehle aktivieren oder deaktivieren Revit-Trägerverbindungen unabhängig am Start- oder Endpunkt ausgewählter Tragwerkselemente."},{"qEn":"What does Sections by SelectionBox do?","aEn":"It creates coordinated section views around a selected model region using a selection-box-based workflow.","qDe":"Was macht Schnitte nach Auswahlbox?","aDe":"Der Befehl erstellt koordinierte Schnittansichten um einen ausgewählten Modellbereich mithilfe eines Auswahlbox-Workflows."},{"qEn":"What does Renumber do?","aEn":"Renumber applies controlled numbering to assembly reinforcement based on the selected scope and configured rules.","qDe":"Was macht Bewehrung nummerieren?","aDe":"Der Befehl weist der Baugruppenbewehrung kontrollierte Nummern anhand des Auswahlbereichs und der konfigurierten Regeln zu."},{"qEn":"What does Partition do?","aEn":"Partition assigns or updates reinforcement partition values for selected bars according to the chosen workflow.","qDe":"Was macht Teilung?","aDe":"Teilung weist ausgewählten Bewehrungsstäben Partitionswerte zu oder aktualisiert diese entsprechend dem gewählten Workflow."},{"qEn":"What is Mesh Cut Plan?","aEn":"Mesh Cut Plan creates organized documentation for fabric sheets, including cut-plan views and related annotations.","qDe":"Was ist Mattenzuschnitt?","aDe":"Mattenzuschnitt erstellt organisierte Dokumentation für Lagermatten, einschließlich Zuschnittsansichten und zugehöriger Beschriftung."},{"qEn":"What is Shape Detail?","aEn":"Shape Detail creates fabric-sheet shape graphics and annotations based on geometry and configured mapping rules.","qDe":"Was ist Formdetail?","aDe":"Formdetail erstellt Formgrafiken und Beschriftungen für Lagermatten anhand der Geometrie und konfigurierter Zuordnungsregeln."},{"qEn":"What is Shape Detail – All?","aEn":"Shape Detail – All generates both shape detail and tagging output for the selected fabric sheets.","qDe":"Was ist Formdetail – Alle?","aDe":"Formdetail – Alle erzeugt sowohl Formdetail als auch Beschriftung für die ausgewählten Lagermatten."},{"qEn":"What is Tag Only?","aEn":"Tag Only places or updates the configured tag without recreating the full shape-detail graphic.","qDe":"Was ist Nur beschriften?","aDe":"Nur beschriften platziert oder aktualisiert die konfigurierte Beschriftung, ohne die vollständige Formdetailgrafik neu zu erstellen."},{"qEn":"What does the Partial option do?","aEn":"The Partial option controls whether partial or hidden fabric information is included in the shape-detail workflow.","qDe":"Was macht die Option Verdeckt?","aDe":"Die Option Verdeckt steuert, ob teilweise beziehungsweise verdeckte Matteninformationen im Formdetail-Workflow berücksichtigt werden."},{"qEn":"What does the Tag option do?","aEn":"The Tag option enables or disables tag creation as part of the fabric-shape-detail operation.","qDe":"Was macht die Option Beschriften?","aDe":"Die Option Beschriften aktiviert oder deaktiviert die Beschriftungserstellung innerhalb des Formdetail-Workflows."},{"qEn":"What does Solve Warnings do?","aEn":"Solve Warnings groups supported Revit warnings and provides focused workflows for reviewing and resolving them.","qDe":"Was macht Warnungen lösen?","aDe":"Warnungen lösen gruppiert unterstützte Revit-Warnungen und bietet fokussierte Abläufe zur Prüfung und Behebung."},{"qEn":"What does Rebar Clashes do?","aEn":"Rebar Clashes checks reinforcement for intersections and helps users review collision locations.","qDe":"Was macht Kollisionen prüfen?","aDe":"Kollisionen prüfen untersucht Bewehrung auf Überschneidungen und unterstützt die Prüfung der Kollisionsstellen."},{"qEn":"Where are AniBIM settings stored?","aEn":"Open the Settings command to review tool defaults, mappings and project-specific preferences. Storage may depend on the feature and deployment configuration.","qDe":"Wo werden AniBIM-Einstellungen verwaltet?","aDe":"Öffnen Sie Einstellungen, um Werkzeugstandards, Zuordnungen und projektspezifische Vorgaben zu prüfen. Der Speicherort kann von Funktion und Bereitstellung abhängen."},{"qEn":"How do I open help?","aEn":"Use Help in the Settings panel to open the AniBIM FT online documentation in your default browser.","qDe":"Wie öffne ich die Hilfe?","aDe":"Verwenden Sie Hilfe im Bereich Einstellungen, um die AniBIM-FT-Onlinedokumentation im Standardbrowser zu öffnen."},{"qEn":"Does AniBIM FT work with German Revit?","aEn":"Yes. AniBIM FT provides English and German ribbon localization, and this website can switch fully between EN and DE.","qDe":"Funktioniert AniBIM FT mit deutschem Revit?","aDe":"Ja. AniBIM FT bietet englische und deutsche Menüband-Lokalisierung; auch diese Website kann vollständig zwischen EN und DE wechseln."},{"qEn":"Can AniBIM FT be deployed to a company?","aEn":"Company deployment can be arranged with machine-bound licensing, standardized settings and support. Contact AniBIM Support for the required scope.","qDe":"Kann AniBIM FT firmenweit verteilt werden?","aDe":"Eine Firmenbereitstellung kann mit maschinengebundener Lizenzierung, standardisierten Einstellungen und Support organisiert werden. Kontaktieren Sie AniBIM Support für den benötigten Umfang."},{"qEn":"Is an internet connection required?","aEn":"The Revit tools are installed locally. Internet access is required for online documentation, support and obtaining installer or licence files.","qDe":"Ist eine Internetverbindung erforderlich?","aDe":"Die Revit-Werkzeuge werden lokal installiert. Internetzugang wird für Onlinedokumentation, Support sowie den Erhalt von Installer- oder Lizenzdateien benötigt."},{"qEn":"How do I download AniBIM FT?","aEn":"Download access is provided to approved trial users and licensed customers from the Download page or directly by AniBIM Support.","qDe":"Wie lade ich AniBIM FT herunter?","aDe":"Downloadzugriff erhalten freigegebene Testnutzer und lizenzierte Kunden über die Downloadseite oder direkt vom AniBIM Support."},{"qEn":"How do I install AniBIM FT?","aEn":"Close Revit, run the correct installer, complete the installation, then start the matching Revit version and follow activation.","qDe":"Wie installiere ich AniBIM FT?","aDe":"Schließen Sie Revit, führen Sie den passenden Installer aus, schließen Sie die Installation ab und starten Sie danach die entsprechende Revit-Version zur Aktivierung."},{"qEn":"Can Revit 2024, 2025, 2026 and 2027 be installed together?","aEn":"Yes. Supported Autodesk Revit versions can coexist. The AniBIM FT installer detects installed versions and lets you select which of Revit 2024–2027 should receive the add-in.","qDe":"Können Revit 2024, 2025, 2026 und 2027 parallel installiert sein?","aDe":"Ja. Unterstützte Autodesk-Revit-Versionen können parallel installiert sein. Der AniBIM-FT-Installer erkennt installierte Versionen und lässt Sie auswählen, für welche Versionen von Revit 2024–2027 das Add-in installiert werden soll."},{"qEn":"What should I do after changing computers?","aEn":"Send the new Machine ID to AniBIM Support and request a replacement licence according to your licence terms.","qDe":"Was muss ich nach einem Computerwechsel tun?","aDe":"Senden Sie die neue Maschinen-ID an AniBIM Support und fordern Sie gemäß Ihren Lizenzbedingungen eine Ersatzlizenz an."},{"qEn":"What if the AniBIM tab is missing?","aEn":"Confirm that the correct version was installed, restart Revit, verify the add-in files and check whether Revit blocked or disabled the add-in.","qDe":"Was tun, wenn die AniBIM-Registerkarte fehlt?","aDe":"Prüfen Sie die installierte Version, starten Sie Revit neu, kontrollieren Sie die Add-in-Dateien und prüfen Sie, ob Revit das Add-in blockiert oder deaktiviert hat."},{"qEn":"What if activation does not open?","aEn":"Restart Revit, confirm the add-in loaded, check installation permissions and contact support with your Revit version and error details.","qDe":"Was tun, wenn die Aktivierung nicht geöffnet wird?","aDe":"Starten Sie Revit neu, prüfen Sie, ob das Add-in geladen wurde, kontrollieren Sie Installationsberechtigungen und senden Sie Revit-Version sowie Fehlerdetails an den Support."},{"qEn":"How do I report a problem?","aEn":"Email AniBIM.Support@gmail.com with the Revit version, AniBIM version, command name, exact steps, screenshots and any error message.","qDe":"Wie melde ich ein Problem?","aDe":"Senden Sie eine E-Mail an AniBIM.Support@gmail.com mit Revit-Version, AniBIM-Version, Befehlsname, genauen Schritten, Screenshots und Fehlermeldung."},{"qEn":"Where can I watch tutorials?","aEn":"Visit the AniBIM Support YouTube channel at @AniBIMSupport from the footer of this website.","qDe":"Wo finde ich Videoanleitungen?","aDe":"Besuchen Sie den YouTube-Kanal AniBIM Support unter @AniBIMSupport über den Footer dieser Website."},{"qEn":"Can I use AniBIM FT in a workshared model?","aEn":"Many commands can be used in workshared projects, but users must have permission to edit the affected elements and should follow company coordination rules.","qDe":"Kann ich AniBIM FT in einem zentralen Modell verwenden?","aDe":"Viele Befehle können in gemeinsam genutzten Projekten verwendet werden. Benutzer benötigen jedoch Bearbeitungsrechte für die betroffenen Elemente und müssen Firmenregeln zur Koordination beachten."},{"qEn":"Does AniBIM FT modify the model?","aEn":"Some tools only change view presentation or selection, while others create or modify model and documentation elements. Review each command workflow before confirming changes.","qDe":"Ändert AniBIM FT das Modell?","aDe":"Einige Werkzeuge ändern nur Ansichtsdarstellung oder Auswahl, andere erstellen oder bearbeiten Modell- und Dokumentationselemente. Prüfen Sie den jeweiligen Ablauf vor der Bestätigung."},{"qEn":"Can I undo AniBIM operations?","aEn":"Model-changing commands normally run inside Revit transactions and can generally be undone with Revit Undo immediately after execution.","qDe":"Kann ich AniBIM-Vorgänge rückgängig machen?","aDe":"Modelländernde Befehle laufen normalerweise in Revit-Transaktionen und können direkt danach in der Regel über Revit Rückgängig zurückgenommen werden."},{"qEn":"Are tool settings project-specific?","aEn":"Some settings are global and others may depend on the active project or configured mappings. Review the Settings page before production use.","qDe":"Sind Werkzeugeinstellungen projektspezifisch?","aDe":"Einige Einstellungen sind global, andere hängen möglicherweise vom aktiven Projekt oder konfigurierten Zuordnungen ab. Prüfen Sie Einstellungen vor dem Produktionseinsatz."},{"qEn":"Can AniBIM create project templates or families?","aEn":"AniBIM FT is the add-in product. Company-specific templates, families and automation can be discussed separately with AniBIM Support.","qDe":"Kann AniBIM Projektvorlagen oder Familien erstellen?","aDe":"AniBIM FT ist das Add-in-Produkt. Firmenspezifische Vorlagen, Familien und Automatisierung können separat mit AniBIM Support besprochen werden."},{"qEn":"Is AniBIM FT only for precast projects?","aEn":"No. It is especially useful for precast and reinforcement workflows, but selection, visibility, modelling and QA tools can benefit other Revit production teams.","qDe":"Ist AniBIM FT nur für Fertigteilprojekte?","aDe":"Nein. Es ist besonders für Fertigteil- und Bewehrungsworkflows nützlich; Auswahl-, Sichtbarkeits-, Modellierungs- und QA-Werkzeuge helfen auch anderen Revit-Produktionsteams."},{"qEn":"How do I find a specific tool in this documentation?","aEn":"Use the orange AniBIM Assistant and ask for the tool name, or use the left ribbon-order navigation to jump directly to its documentation.","qDe":"Wie finde ich ein bestimmtes Werkzeug in der Dokumentation?","aDe":"Verwenden Sie den orangefarbenen AniBIM Assistant und fragen Sie nach dem Werkzeugnamen oder nutzen Sie die linke Navigation in Menüband-Reihenfolge."},{"qEn":"How do I contact AniBIM Support?","aEn":"Email AniBIM.Support@gmail.com. Include enough technical detail to reproduce your question or issue.","qDe":"Wie kontaktiere ich AniBIM Support?","aDe":"Schreiben Sie an AniBIM.Support@gmail.com und geben Sie genügend technische Details an, damit die Frage oder das Problem nachvollzogen werden kann."},{"qEn":"Does AniBIM FT support Revit 2025, 2026 and 2027?","aEn":"Yes. AniBIM FT supports Autodesk Revit 2024, 2025, 2026 and 2027. Use the installer to select the installed Revit versions you want to support.","qDe":"Unterstützt AniBIM FT Revit 2025, 2026 und 2027?","aDe":"Ja. AniBIM FT unterstützt Autodesk Revit 2024, 2025, 2026 und 2027. Wählen Sie im Installer die installierten Revit-Versionen aus, die unterstützt werden sollen."},{"qEn":"Can I install AniBIM FT silently?","aEn":"Company deployment and silent-install requirements can be discussed with AniBIM Support for team licensing.","qDe":"Kann AniBIM FT unbeaufsichtigt installiert werden?","aDe":"Anforderungen für Unternehmensbereitstellung und Silent-Installation können bei Teamlizenzen mit AniBIM Support abgestimmt werden."},{"qEn":"Can settings be shared across a company?","aEn":"Company licensing can include shared settings profiles and deployment guidance so teams use consistent AniBIM configurations.","qDe":"Können Einstellungen firmenweit geteilt werden?","aDe":"Teamlizenzen können gemeinsame Einstellungsprofile und Bereitstellungshinweise enthalten, damit Teams einheitliche AniBIM-Konfigurationen verwenden."},{"qEn":"Does AniBIM require internet access?","aEn":"Normal tool use is designed for Revit desktop workflows. Internet access is needed for website documentation, downloads and support communication.","qDe":"Benötigt AniBIM Internetzugang?","aDe":"Die normale Werkzeugnutzung ist für Revit-Desktopworkflows ausgelegt. Internetzugang wird für Website-Dokumentation, Downloads und Supportkommunikation benötigt."},{"qEn":"Can AniBIM work with linked models?","aEn":"Tool behavior depends on the command. Most model-editing operations target editable elements in the active document; linked elements are generally reference-only.","qDe":"Kann AniBIM mit verknüpften Modellen arbeiten?","aDe":"Das Verhalten hängt vom Befehl ab. Modelländernde Vorgänge bearbeiten normalerweise editierbare Elemente im aktiven Dokument; verknüpfte Elemente dienen meist nur als Referenz."},{"qEn":"How do I update AniBIM FT?","aEn":"Download the approved newer installer, close Revit, run the update and verify the AniBIM tab after restarting Revit.","qDe":"Wie aktualisiere ich AniBIM FT?","aDe":"Laden Sie den freigegebenen neueren Installer herunter, schließen Sie Revit, führen Sie das Update aus und prüfen Sie nach dem Neustart die AniBIM-Registerkarte."},{"qEn":"Will updating remove my settings?","aEn":"Updates are intended to preserve settings where compatible, but company-critical configurations should be documented or backed up before deployment.","qDe":"Werden meine Einstellungen bei einem Update entfernt?","aDe":"Updates sollen kompatible Einstellungen beibehalten. Unternehmenskritische Konfigurationen sollten dennoch vor der Bereitstellung dokumentiert oder gesichert werden."},{"qEn":"Where can I find the AniBIM version number?","aEn":"Check the installed application information, installer name or support details supplied with your build. Include this version when reporting issues.","qDe":"Wo finde ich die AniBIM-Versionsnummer?","aDe":"Prüfen Sie die installierten Programminformationen, den Installernamen oder die mit dem Build gelieferten Supportangaben. Geben Sie diese Version bei Fehlermeldungen an."},{"qEn":"Can I request a demonstration?","aEn":"Yes. Contact AniBIM Support with your company, Revit version and main workflows to arrange a focused demonstration.","qDe":"Kann ich eine Demonstration anfordern?","aDe":"Ja. Kontaktieren Sie AniBIM Support mit Firma, Revit-Version und wichtigsten Workflows, um eine fokussierte Demonstration zu vereinbaren."},{"qEn":"Is training available?","aEn":"Training and onboarding can be discussed for teams, especially when deploying company settings and production workflows.","qDe":"Gibt es Schulungen?","aDe":"Schulungen und Onboarding können für Teams vereinbart werden, besonders bei der Einführung von Firmeneinstellungen und Produktionsworkflows."},{"qEn":"Can AniBIM build custom Revit tools?","aEn":"Yes. Company-specific Revit API tools, Dynamo workflows, families and templates can be scoped separately with AniBIM Support.","qDe":"Kann AniBIM individuelle Revit-Werkzeuge entwickeln?","aDe":"Ja. Firmenspezifische Revit-API-Werkzeuge, Dynamo-Workflows, Familien und Vorlagen können separat mit AniBIM Support geplant werden."},{"qEn":"Can AniBIM automate repetitive tasks?","aEn":"Yes. AniBIM can evaluate repetitive Revit processes and propose add-ins, Dynamo scripts or standardized workflows.","qDe":"Kann AniBIM wiederkehrende Aufgaben automatisieren?","aDe":"Ja. AniBIM kann wiederkehrende Revit-Prozesse analysieren und Add-ins, Dynamo-Skripte oder standardisierte Workflows vorschlagen."},{"qEn":"Can AniBIM provide Revit families?","aEn":"Yes. Parametric and company-standard Revit families can be created as a separate service based on your requirements.","qDe":"Kann AniBIM Revit-Familien bereitstellen?","aDe":"Ja. Parametrische und firmenspezifische Revit-Familien können als separate Leistung nach Ihren Anforderungen erstellt werden."},{"qEn":"Can AniBIM create Revit project templates?","aEn":"Yes. AniBIM can help structure project templates, browser organization, filters, view templates, shared parameters and documentation standards.","qDe":"Kann AniBIM Revit-Projektvorlagen erstellen?","aDe":"Ja. AniBIM kann Projektvorlagen, Browserorganisation, Filter, Ansichtsvorlagen, gemeinsam genutzte Parameter und Dokumentationsstandards strukturieren."},{"qEn":"Can AniBIM create Dynamo tools?","aEn":"Yes. Dynamo and Python-based workflows can be developed for repeatable company tasks and Dynamo Player use.","qDe":"Kann AniBIM Dynamo-Werkzeuge erstellen?","aDe":"Ja. Dynamo- und Python-basierte Workflows können für wiederkehrende Firmenaufgaben und Dynamo Player entwickelt werden."},{"qEn":"Can I suggest a new feature?","aEn":"Yes. Send the workflow, expected result, screenshots and business value to AniBIM Support. Clear examples help evaluate the feature.","qDe":"Kann ich eine neue Funktion vorschlagen?","aDe":"Ja. Senden Sie Workflow, erwartetes Ergebnis, Screenshots und geschäftlichen Nutzen an AniBIM Support. Klare Beispiele erleichtern die Bewertung."},{"qEn":"How are feature requests prioritized?","aEn":"Requests are reviewed by workflow impact, number of users, technical feasibility and alignment with AniBIM FT production goals.","qDe":"Wie werden Funktionswünsche priorisiert?","aDe":"Wünsche werden nach Workflow-Nutzen, Nutzerzahl, technischer Machbarkeit und Übereinstimmung mit den Produktionszielen von AniBIM FT bewertet."},{"qEn":"Can a trial be extended?","aEn":"Trial extensions are considered individually. Contact support before expiry and explain the evaluation status and remaining tests.","qDe":"Kann eine Testversion verlängert werden?","aDe":"Verlängerungen werden individuell geprüft. Kontaktieren Sie den Support vor Ablauf und erläutern Sie Evaluierungsstand und offene Tests."},{"qEn":"What information is needed for a quote?","aEn":"Provide company name, number of users, Revit versions, deployment needs and whether custom configuration or support is required.","qDe":"Welche Angaben werden für ein Angebot benötigt?","aDe":"Nennen Sie Firmenname, Nutzerzahl, Revit-Versionen, Bereitstellungsanforderungen und ob individuelle Konfiguration oder Support benötigt wird."},{"qEn":"Can licences be transferred?","aEn":"Because licences are machine-bound, transfers require support review and a replacement licence under the applicable licence terms.","qDe":"Können Lizenzen übertragen werden?","aDe":"Da Lizenzen maschinengebunden sind, erfordern Übertragungen eine Supportprüfung und eine Ersatzlizenz gemäß den geltenden Lizenzbedingungen."},{"qEn":"Does AniBIM collect project data?","aEn":"The add-in is designed for local Revit workflows. For exact data-handling details of a specific build, request the current licensing and privacy information from support.","qDe":"Erfasst AniBIM Projektdaten?","aDe":"Das Add-in ist für lokale Revit-Workflows ausgelegt. Für genaue Angaben zur Datenverarbeitung eines Builds fordern Sie aktuelle Lizenz- und Datenschutzinformationen beim Support an."},{"qEn":"How do I prepare a good support request?","aEn":"Include the command, Revit version, AniBIM version, project context, exact reproduction steps, screenshots and the full error message.","qDe":"Wie erstelle ich eine gute Supportanfrage?","aDe":"Geben Sie Befehl, Revit-Version, AniBIM-Version, Projektkontext, genaue Reproduktionsschritte, Screenshots und vollständige Fehlermeldung an."},{"qEn":"What does the Settings command control?","aEn":"Settings opens AniBIM configuration pages for supported tools, mappings and behavior. Available pages depend on the installed build.","qDe":"Was steuert der Befehl Einstellungen?","aDe":"Einstellungen öffnet AniBIM-Konfigurationsseiten für unterstützte Werkzeuge, Zuordnungen und Verhalten. Verfügbare Seiten hängen vom installierten Build ab."},{"qEn":"Can I reset AniBIM settings?","aEn":"Reset options depend on the settings page and build. Record important company values before resetting and contact support when uncertain.","qDe":"Kann ich AniBIM-Einstellungen zurücksetzen?","aDe":"Zurücksetzoptionen hängen von Einstellungsseite und Build ab. Dokumentieren Sie wichtige Firmenwerte vorher und kontaktieren Sie bei Unsicherheit den Support."},{"qEn":"Why does a command require a selection?","aEn":"Many AniBIM tools intentionally operate on a controlled Revit selection to keep changes predictable and limited to the intended scope.","qDe":"Warum benötigt ein Befehl eine Auswahl?","aDe":"Viele AniBIM-Werkzeuge arbeiten bewusst mit einer kontrollierten Revit-Auswahl, damit Änderungen vorhersehbar und auf den vorgesehenen Bereich begrenzt bleiben."},{"qEn":"What should I select for Assembly Creator?","aEn":"Select the production elements that must become members of the new assembly, then follow the dialog to choose the main member and naming options.","qDe":"Was soll ich für den Baugruppenersteller auswählen?","aDe":"Wählen Sie die Produktionselemente der neuen Baugruppe aus und folgen Sie dem Dialog zur Wahl von Hauptbauteil und Benennungsoptionen."},{"qEn":"Can Assembly Editor remove members?","aEn":"Yes. Assembly Editor is intended to review and update existing assembly membership, including adding or removing eligible elements.","qDe":"Kann der Baugruppen-Editor Mitglieder entfernen?","aDe":"Ja. Der Baugruppen-Editor dient zur Prüfung und Aktualisierung vorhandener Baugruppenmitglieder, einschließlich Hinzufügen oder Entfernen geeigneter Elemente."},{"qEn":"How does Rule Selection improve consistency?","aEn":"It lets users apply repeatable property criteria instead of manually clicking elements, reducing omissions and inconsistent selection scope.","qDe":"Wie verbessert Regelauswahl die Konsistenz?","aDe":"Sie verwendet wiederholbare Eigenschaftskriterien statt manueller Elementauswahl und reduziert dadurch Auslassungen und uneinheitliche Auswahlbereiche."},{"qEn":"Can Select Similar use multiple properties?","aEn":"The custom selection option is intended for more controlled matching. Available criteria depend on the installed version and command dialog.","qDe":"Kann Ähnliche auswählen mehrere Eigenschaften verwenden?","aDe":"Die benutzerdefinierte Auswahl ist für kontrolliertere Vergleiche vorgesehen. Verfügbare Kriterien hängen von installierter Version und Befehlsdialog ab."},{"qEn":"Does Spotlight permanently change graphics?","aEn":"Spotlight is intended as a focused view-presentation workflow. Confirm the command behavior in your build and use Revit Undo when a temporary result must be reverted.","qDe":"Ändert Hervorheben Grafiken dauerhaft?","aDe":"Hervorheben ist als fokussierter Ansichtsdarstellungsworkflow gedacht. Prüfen Sie das Verhalten Ihres Builds und verwenden Sie Revit Rückgängig, wenn ein temporäres Ergebnis zurückgesetzt werden soll."},{"qEn":"When should I use Transparent Selected?","aEn":"Use it when selected elements obstruct the view of reinforcement, connections or geometry behind them during review.","qDe":"Wann sollte ich Transparent verwenden?","aDe":"Verwenden Sie es, wenn ausgewählte Elemente bei der Prüfung Bewehrung, Verbindungen oder dahinterliegende Geometrie verdecken."},{"qEn":"What happens when Toggle Parts is unavailable?","aEn":"The active view or selected elements may not support Parts display. Check Revit Parts creation and the view's Parts Visibility setting.","qDe":"Was passiert, wenn Teile umschalten nicht verfügbar ist?","aDe":"Die aktive Ansicht oder ausgewählten Elemente unterstützen möglicherweise keine Teiledarstellung. Prüfen Sie Revit-Teile und die Einstellung Teilesichtbarkeit der Ansicht."},{"qEn":"Can Beam Length work on sloped beams?","aEn":"Behavior depends on framing geometry and constraints. Test the tool on representative elements and verify endpoints and joins after editing.","qDe":"Funktioniert Trägerlänge bei geneigten Trägern?","aDe":"Das Verhalten hängt von Geometrie und Abhängigkeiten ab. Testen Sie das Werkzeug an repräsentativen Elementen und prüfen Sie Endpunkte und Verbindungen danach."},{"qEn":"Why control beam joins separately?","aEn":"Independent start and end join controls help resolve framing-end behavior without changing the opposite end.","qDe":"Warum werden Trägerverbindungen getrennt gesteuert?","aDe":"Getrennte Start- und Endsteuerungen helfen, das Verhalten eines Trägerendes zu korrigieren, ohne das andere Ende zu verändern."},{"qEn":"What views are created by Sections by SelectionBox?","aEn":"The command creates coordinated section views around the selected region according to its configured view-generation workflow.","qDe":"Welche Ansichten erstellt Schnitte nach Auswahlbox?","aDe":"Der Befehl erstellt koordinierte Schnittansichten um den ausgewählten Bereich entsprechend dem konfigurierten Ansichtserstellungsworkflow."},{"qEn":"Can Renumber overwrite existing numbers?","aEn":"It can update numbering within the chosen scope. Review the dialog, selected assemblies and current marks before confirming.","qDe":"Kann Nummerieren vorhandene Nummern überschreiben?","aDe":"Der Befehl kann Nummern im gewählten Bereich aktualisieren. Prüfen Sie Dialog, ausgewählte Baugruppen und aktuelle Kennzeichnungen vor der Bestätigung."},{"qEn":"Why use reinforcement partitions?","aEn":"Partitions organize reinforcement into controlled groups for schedules, documentation, filtering and production coordination.","qDe":"Warum Bewehrungspartitionen verwenden?","aDe":"Partitionen organisieren Bewehrung in kontrollierten Gruppen für Listen, Dokumentation, Filterung und Produktionskoordination."},{"qEn":"What input does Mesh Cut Plan need?","aEn":"Select the relevant fabric sheets and ensure required project families, view settings and mappings are configured before generating documentation.","qDe":"Welche Eingaben benötigt Mattenzuschnitt?","aDe":"Wählen Sie die relevanten Lagermatten und stellen Sie sicher, dass benötigte Projektfamilien, Ansichtseinstellungen und Zuordnungen konfiguriert sind."},{"qEn":"Why is a Shape Detail image missing?","aEn":"Confirm that the selected fabric sheet is supported, required detail families are loaded and the configured parameter mapping is valid.","qDe":"Warum fehlt eine Formdetailgrafik?","aDe":"Prüfen Sie, ob die ausgewählte Lagermatte unterstützt wird, benötigte Detailfamilien geladen und Parameterzuordnungen gültig sind."},{"qEn":"Can Shape Detail update after fabric changes?","aEn":"The workflow is designed to create mapped detail output. Whether existing details update automatically depends on the command implementation and project setup.","qDe":"Aktualisiert sich Formdetail nach Mattenänderungen?","aDe":"Der Workflow erstellt zugeordnete Detailausgaben. Ob vorhandene Details automatisch aktualisiert werden, hängt von Befehlsimplementierung und Projektaufbau ab."},{"qEn":"What warnings can Solve Warnings resolve?","aEn":"The tool focuses on supported warning categories and guided actions. Unsupported warnings still require standard Revit review.","qDe":"Welche Warnungen kann Warnungen lösen beheben?","aDe":"Das Werkzeug konzentriert sich auf unterstützte Warnungskategorien und geführte Aktionen. Nicht unterstützte Warnungen müssen weiterhin in Revit geprüft werden."},{"qEn":"Does Rebar Clashes replace full coordination software?","aEn":"No. It provides focused reinforcement collision checks inside Revit and complements, rather than replaces, broader coordination workflows.","qDe":"Ersetzt Kollisionen prüfen vollständige Koordinationssoftware?","aDe":"Nein. Es bietet fokussierte Bewehrungskollisionsprüfungen in Revit und ergänzt umfassendere Koordinationsworkflows."},{"qEn":"How can I improve Rebar Clashes performance?","aEn":"Limit the check to a meaningful model scope, close unnecessary views and use representative selections instead of checking unrelated project content.","qDe":"Wie verbessere ich die Leistung von Kollisionen prüfen?","aDe":"Begrenzen Sie die Prüfung auf einen sinnvollen Modellbereich, schließen Sie unnötige Ansichten und vermeiden Sie unzusammenhängende Projektinhalte."},{"qEn":"Can AniBIM documentation be used offline?","aEn":"The GitHub Pages site is online. A company may save approved pages locally, but updates and linked resources are best accessed online.","qDe":"Kann die AniBIM-Dokumentation offline genutzt werden?","aDe":"Die GitHub-Pages-Website ist online. Freigegebene Seiten können lokal gespeichert werden; Updates und verknüpfte Ressourcen sind online am zuverlässigsten."},{"qEn":"How do I switch the website language?","aEn":"Use EN or DE in the top navigation. The selected language is kept while moving between AniBIM website pages.","qDe":"Wie wechsle ich die Website-Sprache?","aDe":"Verwenden Sie EN oder DE in der oberen Navigation. Die gewählte Sprache bleibt beim Wechsel zwischen AniBIM-Seiten erhalten."},{"qEn":"What can the AniBIM Assistant answer?","aEn":"It contains 100 predefined bilingual answers about AniBIM FT, tools, Revit versions, licensing, installation and support.","qDe":"Was kann der AniBIM Assistant beantworten?","aDe":"Er enthält 100 vordefinierte zweisprachige Antworten zu AniBIM FT, Werkzeugen, Revit-Versionen, Lizenzierung, Installation und Support."},{"qEn":"Is the AniBIM Assistant an online AI service?","aEn":"No. The current website assistant uses a local predefined knowledge base in the page and does not send chat text to an external AI service.","qDe":"Ist der AniBIM Assistant ein Online-KI-Dienst?","aDe":"Nein. Der aktuelle Website-Assistent verwendet eine lokale vordefinierte Wissensbasis und sendet Chattexte nicht an einen externen KI-Dienst."},{"qEn":"How do related questions work?","aEn":"After each answer, the assistant offers relevant follow-up questions so you can explore the topic as a guided conversation tree.","qDe":"Wie funktionieren verwandte Fragen?","aDe":"Nach jeder Antwort bietet der Assistent passende Folgefragen an, sodass Sie das Thema als geführten Gesprächsbaum erkunden können."},{"qEn":"Can I open the assistant on every page?","aEn":"Yes. The orange AniBIM Assistant button is available on every main website page.","qDe":"Kann ich den Assistenten auf jeder Seite öffnen?","aDe":"Ja. Der orangefarbene AniBIM-Assistant-Button ist auf jeder Hauptseite der Website verfügbar."},{"qEn":"What should I ask first?","aEn":"Start with your goal: selecting elements, creating assemblies, controlling visibility, documenting reinforcement, resolving warnings or installing AniBIM.","qDe":"Was sollte ich zuerst fragen?","aDe":"Beginnen Sie mit Ihrem Ziel: Elemente auswählen, Baugruppen erstellen, Sichtbarkeit steuern, Bewehrung dokumentieren, Warnungen lösen oder AniBIM installieren."}];
 function injectAssistant(){
  if(document.getElementById('anibim-assistant-trigger')) return;
  document.body.insertAdjacentHTML('beforeend',`<button id="anibim-assistant-trigger" class="anibim-assistant-trigger" type="button" aria-label="Open AniBIM Assistant"><span class="assistant-orbit-wrap"><span class="assistant-core">A</span><span class="assistant-orbit"></span></span><span class="assistant-trigger-copy"><strong>AniBIM Assistant</strong><small data-lang="en">Ask about AniBIM FT</small><small data-lang="de">Fragen zu AniBIM FT</small></span></button><section id="anibim-assistant" class="anibim-assistant" aria-hidden="true"><div class="assistant-panel"><div class="assistant-head"><div class="assistant-avatar">A</div><div><strong><i></i>AniBIM Assistant</strong><span data-lang="en">100 guided answers · local & private</span><span data-lang="de">100 geführte Antworten · lokal & privat</span></div><button id="assistant-close" type="button" aria-label="Close">×</button></div><div id="assistant-messages" class="assistant-messages"></div><div id="assistant-suggestions" class="assistant-suggestions"></div><form id="assistant-form" class="assistant-compose"><input id="assistant-input" autocomplete="off" data-placeholder-en="Ask about AniBIM FT…" data-placeholder-de="Fragen Sie zu AniBIM FT…" placeholder="Ask about AniBIM FT…"><button type="submit" aria-label="Send">➜</button></form><footer><span data-lang="en">Predefined AniBIM knowledge · no data is sent</span><span data-lang="de">Vordefiniertes AniBIM-Wissen · keine Datenübertragung</span></footer></div></section>`);
 }
 injectAssistant();
 const trigger=document.getElementById('anibim-assistant-trigger'),panel=document.getElementById('anibim-assistant'),close=document.getElementById('assistant-close'),messages=document.getElementById('assistant-messages'),suggestions=document.getElementById('assistant-suggestions'),form=document.getElementById('assistant-form'),input=document.getElementById('assistant-input');
 if(!trigger||!panel||!messages||!form||!input)return;
 const lang=()=>document.body.classList.contains('lang-de')?'de':'en';
 const text=(f,k)=>f[k+(lang()==='de'?'De':'En')];
 const esc=s=>String(s).replace(/[&<>"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
 function add(role,html){const row=document.createElement('div');row.className='assistant-message '+role;row.innerHTML='<div class="assistant-bubble">'+html+'</div>';messages.appendChild(row);messages.scrollTop=messages.scrollHeight;return row}
 function topicWords(f){return (f.qEn+' '+f.qDe+' '+f.aEn+' '+f.aDe).toLowerCase().split(/[^a-z0-9äöüß]+/).filter(w=>w.length>3)}
 function related(index,count=4){const base=new Set(topicWords(FAQS[index]));return FAQS.map((f,i)=>({i,s:i===index?-1:topicWords(f).reduce((n,w)=>n+(base.has(w)?1:0),0)})).sort((a,b)=>b.s-a.s).slice(0,count).map(x=>x.i)}
 function renderChips(ids,label){suggestions.innerHTML=(label?'<span class="assistant-follow-label">'+esc(label)+'</span>':'')+ids.map(i=>'<button class="assistant-chip" type="button" data-faq="'+i+'">'+esc(text(FAQS[i],'q'))+'</button>').join('')}
 function welcome(){messages.innerHTML='';add('bot',lang()==='de'?'<strong>Hallo, ich bin der AniBIM Assistant.</strong><br>Stellen Sie eine Frage oder wählen Sie einen Einstieg. Ich führe Sie mit passenden Folgefragen weiter.':'<strong>Hi, I’m the AniBIM Assistant.</strong><br>Ask a question or choose a starting point. I will guide you with relevant follow-up questions.');renderChips([0,1,2,10,21,41],lang()==='de'?'Beliebte Themen':'Popular topics')}
 function score(f,q){const hay=(f.qEn+' '+f.qDe+' '+f.aEn+' '+f.aDe).toLowerCase();const words=q.toLowerCase().split(/[^a-z0-9äöüß]+/).filter(w=>w.length>2);return words.reduce((n,w)=>n+(hay.includes(w)?1:0),0)}
 function answerIndex(i,question){if(question)add('user',esc(question));const typing=add('bot','<span class="assistant-typing"><i></i><i></i><i></i></span>');setTimeout(()=>{typing.remove();const f=FAQS[i];add('bot','<strong>'+esc(text(f,'q'))+'</strong><br>'+esc(text(f,'a')));renderChips(related(i),lang()==='de'?'Passende nächste Fragen':'Relevant next questions')},360)}
 function answerQuery(q){const ranked=FAQS.map((f,i)=>({i,s:score(f,q)})).sort((a,b)=>b.s-a.s);if(!ranked[0]||ranked[0].s===0){add('user',esc(q));add('bot',lang()==='de'?'Dazu habe ich keine sichere vordefinierte Antwort. Wählen Sie unten ein verwandtes Thema oder kontaktieren Sie <a href="mailto:AniBIM.Support@gmail.com">AniBIM Support</a>.':'I do not have a confident predefined answer for that. Choose a related topic below or contact <a href="mailto:AniBIM.Support@gmail.com">AniBIM Support</a>.');renderChips([0,1,2,31,41],lang()==='de'?'Versuchen Sie diese Themen':'Try these topics')}else answerIndex(ranked[0].i,q)}
 function open(){panel.classList.add('open');panel.setAttribute('aria-hidden','false');if(!messages.children.length)welcome();setTimeout(()=>input.focus(),60)}
 function shut(){panel.classList.remove('open');panel.setAttribute('aria-hidden','true')}
 trigger.addEventListener('click',()=>panel.classList.contains('open')?shut():open());close.addEventListener('click',shut);form.addEventListener('submit',e=>{e.preventDefault();const q=input.value.trim();if(q){input.value='';answerQuery(q)}});suggestions.addEventListener('click',e=>{const b=e.target.closest('[data-faq]');if(b)answerIndex(+b.dataset.faq,text(FAQS[+b.dataset.faq],'q'))});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&panel.classList.contains('open'))shut()});document.addEventListener('anibim-language-changed',()=>{document.querySelectorAll('[data-placeholder-'+lang()+']').forEach(e=>e.placeholder=e.getAttribute('data-placeholder-'+lang()));if(panel.classList.contains('open'))welcome()});
})();

// V10 Assistant desktop behavior: draggable, resizable and persistent.
(function enhanceAssistantWorkspace(){
 const assistant=document.getElementById('anibim-assistant');
 if(!assistant||assistant.dataset.workspaceReady==='true') return;
 assistant.dataset.workspaceReady='true';
 const panel=assistant.querySelector('.assistant-panel');
 const head=assistant.querySelector('.assistant-head');
 const close=assistant.querySelector('#assistant-close');
 if(!panel||!head) return;

 let handle=panel.querySelector('.assistant-resize-handle');
 if(!handle){
   handle=document.createElement('span');
   handle.className='assistant-resize-handle';
   handle.setAttribute('role','separator');
   handle.setAttribute('aria-label','Resize AniBIM Assistant');
   panel.appendChild(handle);
 }

 const storageKey='anibim-assistant-workspace-v10';
 const clamp=(value,min,max)=>Math.min(Math.max(value,min),max);
 const isDesktop=()=>window.matchMedia('(min-width:701px)').matches;
 function bounds(){return {w:window.innerWidth,h:window.innerHeight}}
 function normalizePosition(left,top,width,height){
   const b=bounds(),margin=10;
   return {
     left:clamp(left,margin,Math.max(margin,b.w-width-margin)),
     top:clamp(top,margin,Math.max(margin,b.h-height-margin))
   };
 }
 function applySaved(){
   if(!isDesktop()) return;
   try{
     const s=JSON.parse(localStorage.getItem(storageKey)||'null');
     if(!s) return;
     const width=clamp(Number(s.width)||470,390,window.innerWidth*.82);
     const height=clamp(Number(s.height)||680,520,window.innerHeight*.88);
     const p=normalizePosition(Number(s.left)||24,Number(s.top)||24,width,height);
     Object.assign(assistant.style,{left:p.left+'px',top:p.top+'px',right:'auto',bottom:'auto',width:width+'px',height:height+'px'});
   }catch(e){}
 }
 function save(){
   if(!isDesktop()) return;
   const r=assistant.getBoundingClientRect();
   try{localStorage.setItem(storageKey,JSON.stringify({left:r.left,top:r.top,width:r.width,height:r.height}))}catch(e){}
 }
 function keepInside(){
   if(!isDesktop()||!assistant.classList.contains('open')) return;
   const r=assistant.getBoundingClientRect();
   const width=Math.min(r.width,window.innerWidth*.82),height=Math.min(r.height,window.innerHeight*.88);
   const p=normalizePosition(r.left,r.top,width,height);
   Object.assign(assistant.style,{left:p.left+'px',top:p.top+'px',right:'auto',bottom:'auto',width:width+'px',height:height+'px'});
   save();
 }

 function startInteraction(event,mode){
   if(!isDesktop()||event.button!==0) return;
   if(mode==='move'&&(event.target.closest('button,input,a,.assistant-chip'))) return;
   event.preventDefault();
   const start=assistant.getBoundingClientRect();
   const startX=event.clientX,startY=event.clientY;
   assistant.classList.add(mode==='move'?'is-moving':'is-resizing');
   document.body.classList.add('assistant-interacting');
   event.currentTarget.setPointerCapture?.(event.pointerId);
   function move(e){
     if(mode==='move'){
       const p=normalizePosition(start.left+(e.clientX-startX),start.top+(e.clientY-startY),start.width,start.height);
       Object.assign(assistant.style,{left:p.left+'px',top:p.top+'px',right:'auto',bottom:'auto'});
     }else{
       const maxW=window.innerWidth-start.left-10,maxH=window.innerHeight-start.top-10;
       const width=clamp(start.width+(e.clientX-startX),390,Math.min(window.innerWidth*.82,maxW));
       const height=clamp(start.height+(e.clientY-startY),520,Math.min(window.innerHeight*.88,maxH));
       Object.assign(assistant.style,{width:width+'px',height:height+'px',right:'auto',bottom:'auto'});
     }
   }
   function end(){
     window.removeEventListener('pointermove',move);
     window.removeEventListener('pointerup',end);
     window.removeEventListener('pointercancel',end);
     assistant.classList.remove('is-moving','is-resizing');
     document.body.classList.remove('assistant-interacting');
     save();
   }
   window.addEventListener('pointermove',move);
   window.addEventListener('pointerup',end,{once:true});
   window.addEventListener('pointercancel',end,{once:true});
 }
 head.addEventListener('pointerdown',e=>startInteraction(e,'move'));
 handle.addEventListener('pointerdown',e=>startInteraction(e,'resize'));
 close?.addEventListener('pointerdown',e=>e.stopPropagation());
 window.addEventListener('resize',keepInside);

 // Apply stored geometry immediately and whenever the assistant opens.
 applySaved();
 const observer=new MutationObserver(()=>{if(assistant.classList.contains('open')){if(!assistant.style.left) applySaved();setTimeout(keepInside,0)}});
 observer.observe(assistant,{attributes:true,attributeFilter:['class']});
})();


// AniBIM F1 contextual help integration
(function(){
 const params=new URLSearchParams(window.location.search);
 const fromRevit=params.get('from')==='revit';
 const toolKey=params.get('tool')||'';
 const rawHash=decodeURIComponent((window.location.hash||'').replace(/^#/,''));
 if(!fromRevit && !rawHash)return;

 function focusDocumentationTarget(){
  if(!rawHash)return;
  const target=document.getElementById(rawHash);
  if(!target)return;

  // Wait until language and layout updates have completed.
  requestAnimationFrame(()=>requestAnimationFrame(()=>{
   target.scrollIntoView({behavior:'smooth',block:'start'});
   target.classList.remove('opened-from-revit');
   void target.offsetWidth;
   target.classList.add('opened-from-revit');

   if(fromRevit){
    const lang=document.body.classList.contains('lang-de')?'de':'en';
    const notice=document.createElement('div');
    notice.className='revit-f1-notice';
    notice.setAttribute('role','status');
    notice.innerHTML='<span class="revit-f1-notice-icon">F1</span><div><strong>'+
      (lang==='de'?'Aus Revit geöffnet':'Opened from Revit')+
      '</strong><small>'+(lang==='de'?'Kontexthilfe für dieses AniBIM-FT-Werkzeug':'Context help for this AniBIM FT tool')+'</small></div>';
    document.body.appendChild(notice);
    setTimeout(()=>notice.classList.add('show'),40);
    setTimeout(()=>{notice.classList.remove('show');setTimeout(()=>notice.remove(),260)},4200);

    // Share the originating tool with the local AniBIM Assistant when available.
    try{sessionStorage.setItem('anibim-f1-tool',toolKey)}catch(e){}
   }

   setTimeout(()=>target.classList.remove('opened-from-revit'),3600);
  }));
 }

 if(document.readyState==='loading'){
  document.addEventListener('DOMContentLoaded',focusDocumentationTarget,{once:true});
 }else{
  focusDocumentationTarget();
 }
 window.addEventListener('hashchange',focusDocumentationTarget);
})();
